import java.util.*;

class EventBus {
    private Map<String, List<Consumer>> listeners = new HashMap<>();

    interface Consumer {
        void accept(String data);
    }

    public void subscribe(String event, Consumer c) {
        listeners.computeIfAbsent(event, k -> new ArrayList<>()).add(c);
    }

    public void emit(String event, String data) {
        if (listeners.containsKey(event)) {
            for (Consumer c : listeners.get(event)) {
                c.accept(data);
            }
        }
    }
}

public class Main {
    public static void main(String[] args) {
        EventBus bus = new EventBus();

        bus.subscribe("user_created", data -> System.out.println("Event: " + data));

        bus.emit("user_created", "User 1");
    }
}

import java.util.*;

class Cache {
    private class Item {
        String value;
        long expiry;

        Item(String value, long ttl) {
            this.value = value;
            this.expiry = System.currentTimeMillis() + ttl;
        }
    }

    private Map<String, Item> store = new HashMap<>();

    public void set(String key, String value, long ttl) {
        store.put(key, new Item(value, ttl));
    }

    public String get(String key) {
        Item item = store.get(key);
        if (item == null || System.currentTimeMillis() > item.expiry) {
            return null;
        }
        return item.value;
    }
}

