import java.util.*;

class Scheduler {
    private Queue<String> tasks = new LinkedList<>();

    public void addTask(String task) {
        tasks.add(task);
    }

    public void run() {
        while (!tasks.isEmpty()) {
            System.out.println("Executing: " + tasks.poll());
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Scheduler s = new Scheduler();
        s.addTask("Job 1");
        s.addTask("Job 2");

        s.run();
    }
}
